mapper.select:
SELECT u.user_idx, u.user_id, u.user_email, u.nickname, u.account_status, u.member_grade, u.cash_balance, u.mileage_balance, u.point_balance, u.created_at, u.last_login_at FROM USERS u
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') OR u.user_id LIKE CONCAT('%', #{keyword}, '%'))
AND u.member_grade = #{memberGrade}
ORDER BY
u.cash_balance DESC u.mileage_balance DESC FIELD(u.member_grade, 'PLATINUM','DIAMOND','GOLD','SILVER','BRONZE'), u.user_idx DESC u.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM USERS u
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR u.user_email LIKE CONCAT('%', #{keyword}, '%') OR u.user_id LIKE CONCAT('%', #{keyword}, '%'))
AND u.member_grade = #{memberGrade}
